// --- Test allTokensInBlock() with a custom token generator

(() => {
	const charGenerator: TTokenGenerator = function*(line: string) {
		for (const ch of line) {
			yield {kind: 'char', str: ch}
		}
		return
	}

	unifies(Array.from(allTokensInBlock(`abc
	def`, charGenerator)), [
		{ kind: "char", str: "a" },
		{ kind: "char", str: "b" },
		{ kind: "char", str: "c" },
		{ kind: "indent"},
		{ kind: "char", str: "d" },
		{ kind: "char", str: "e" },
		{ kind: "char", str: "f" },
		{ kind: "undent"},
		{kind: 'eof'}
		])
}
	)();

(() => {
	const niceGenerator: TTokenGenerator = function*(line: string) {
		let ref;if ((ref = line.match(/^-\s+(.*)$/))) {let lMatches = ref;
			yield {
				kind: 'list-item',
				str: line,
				value: lMatches[1]
				}
		}
		else {
			yield {
				kind: 'line',
				str: line
				}
		}
		return
	}

	unifies(Array.from(allTokensInBlock(`- a
- b`, niceGenerator)), [
		{ kind: "list-item", str: "- a", value: "a" },
		{ kind: "list-item", str: "- b", value: "b" },
		{kind: 'eof'}
		])
}
	)()

